const tipos = {
  identity: 'Documento de identidad',
  icfes: 'Resultado ICFES',
  diploma: 'Diploma de bachiller',
  acta: 'Acta de grado',
  adicional: 'Documento adicional'
};
return items.map(item => ({
  json: {
    to: item.json.email || 'sin-correo@demo.local',
    subject: 'SION UNAC - Documento recibido: ' + (tipos[item.json.docType] || item.json.docType),
    name: item.json.name || 'Aspirante',
    docType: item.json.docType,
    program: item.json.program,
    body: 'Hola ' + (item.json.name || 'Aspirante') + ', recibimos tu documento ' + (tipos[item.json.docType] || item.json.docType) + ' para el programa ' + item.json.program + '. Estado: ' + item.json.status + '.',
    sentAt: new Date().toISOString()
  }
}));
